Here's a Python function that lists every file in a given path along with its SHA256 hash:

```python
import os
import hashlib
from pathlib import Path

def list_files_with_sha256(path):
    """
    List all files in the given path with their SHA256 hashes.

    Args:
        path (str): The directory path to scan for files

    Returns:
        dict: A dictionary with file paths as keys and SHA256 hashes as values
    """
    def calculate_sha256(file_path):
        """Calculate SHA256 hash of a file."""
        sha256_hash = hashlib.sha256()
        try:
            with open(file_path, "rb") as f:
                # Read file in chunks to handle large files efficiently
                for chunk in iter(lambda: f.read(8192), b""):
                    sha256_hash.update(chunk)
            return sha256_hash.hexdigest()
        except (IOError, OSError) as e:
            return f"Error: {str(e)}"

    results = {}
    path = Path(path)

    if not path.exists():
        raise ValueError(f"Path '{path}' does not exist")

    if path.is_file():
        # If path is a file, just hash that single file
        results[str(path)] = calculate_sha256(path)
    elif path.is_dir():
        # If path is a directory, walk through all files
        for root, dirs, files in os.walk(path):
            for file in files:
                file_path = os.path.join(root, file)
                results[file_path] = calculate_sha256(file_path)

    return results

def print_files_with_sha256(path, show_relative_paths=False):
    """
    Print files and their SHA256 hashes in a formatted way.

    Args:
        path (str): The directory path to scan for files
        show_relative_paths (bool): If True, show relative paths instead of absolute
    """
    try:
        file_hashes = list_files_with_sha256(path)

        if not file_hashes:
            print("No files found in the specified path.")
            return

        base_path = Path(path).resolve()

        for file_path, hash_value in file_hashes.items():
            if show_relative_paths and Path(file_path).is_absolute():
                try:
                    display_path = Path(file_path).relative_to(base_path.parent)
                except ValueError:
                    display_path = file_path
            else:
                display_path = file_path

            print(f"{hash_value}  {display_path}")

    except ValueError as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")

# Example usage
if __name__ == "__main__":
    # Example 1: List files in current directory
    print("Files in current directory:")
    print_files_with_sha256(".")

    # Example 2: Get dictionary of file hashes
    # file_dict = list_files_with_sha256("/path/to/directory")
    # for file_path, hash_val in file_dict.items():
    #     print(f"{hash_val}  {file_path}")
```

