import os
import hashlib
from pathlib import Path
import json
from typing import Optional, Dict, List

def list_files_with_sha256_advanced(
    path: str,
    recursive: bool = True,
    file_extensions: Optional[List[str]] = None,
    exclude_patterns: Optional[List[str]] = None,
    output_format: str = "dict"
) -> Dict[str, str]:
    """
    Advanced version with filtering and output options.

    Args:
        path: The directory path to scan for files
        recursive: If True, scan subdirectories recursively
        file_extensions: List of file extensions to include (e.g., ['.txt', '.pdf'])
        exclude_patterns: List of patterns to exclude from results
        output_format: Output format ('dict', 'json', 'csv')

    Returns:
        Dictionary with file paths and their SHA256 hashes
    """
    def calculate_sha256(file_path):
        sha256_hash = hashlib.sha256()
        try:
            with open(file_path, "rb") as f:
                for chunk in iter(lambda: f.read(8192), b""):
                    sha256_hash.update(chunk)
            return sha256_hash.hexdigest()
        except Exception as e:
            return f"Error: {str(e)}"

    def should_include_file(file_path):
        """Check if file should be included based on filters."""
        file_path_obj = Path(file_path)

        # Check file extensions
        if file_extensions:
            if file_path_obj.suffix.lower() not in [ext.lower() for ext in file_extensions]:
                return False

        # Check exclude patterns
        if exclude_patterns:
            for pattern in exclude_patterns:
                if pattern in str(file_path):
                    return False

        return True

    results = {}
    path_obj = Path(path)

    if not path_obj.exists():
        raise ValueError(f"Path '{path}' does not exist")

    if path_obj.is_file():
        if should_include_file(path_obj):
            results[str(path_obj)] = calculate_sha256(path_obj)
    elif path_obj.is_dir():
        if recursive:
            pattern = "**/*" if recursive else "*"
            for file_path in path_obj.glob(pattern):
                if file_path.is_file() and should_include_file(file_path):
                    results[str(file_path)] = calculate_sha256(file_path)

    # Format output based on preference
    if output_format == "json":
        return json.dumps(results, indent=2)
    elif output_format == "csv":
        csv_lines = ["File Path,SHA256 Hash"]
        for file_path, hash_val in results.items():
            csv_lines.append(f'"{file_path}","{hash_val}"')
        return "\n".join(csv_lines)
    else:
        return results

# Example with progress bar (requires tqdm: pip install tqdm)
def list_files_with_sha256_progress(path: str) -> Dict[str, str]:
    """Version with progress bar for large directories."""
    try:
        from tqdm import tqdm
    except ImportError:
        print("Install tqdm for progress bar: pip install tqdm")
        return list_files_with_sha256(path)

    def calculate_sha256(file_path):
        sha256_hash = hashlib.sha256()
        try:
            with open(file_path, "rb") as f:
                for chunk in iter(lambda: f.read(8192), b""):
                    sha256_hash.update(chunk)
            return sha256_hash.hexdigest()
        except Exception as e:
            return f"Error: {str(e)}"

    results = {}
    path_obj = Path(path)

    if not path_obj.exists():
        raise ValueError(f"Path '{path}' does not exist")

    # Get all files first
    all_files = []
    if path_obj.is_file():
        all_files = [path_obj]
    else:
        all_files = [f for f in path_obj.rglob("*") if f.is_file()]

    # Process with progress bar
    for file_path in tqdm(all_files, desc="Calculating SHA256 hashes"):
        results[str(file_path)] = calculate_sha256(file_path)

    return results

# Example usage
if __name__ == "__main__":
    # Basic usage
    hashes = list_files_with_sha256(".")
    for file_path, hash_val in hashes.items():
        print(f"{hash_val}  {file_path}")

    # Advanced usage with filters
    # hashes = list_files_with_sha256_advanced(
    #     path=".",
    #     file_extensions=[".py", ".txt"],
    #     exclude_patterns=["__pycache__", ".git"],
    #     output_format="dict"
    # )
```

Key features of these functions:

1. **Basic function** (`list_files_with_sha256`):
   - Takes a path as input
   - Returns a dictionary with file paths as keys and SHA256 hashes as values
   - Handles both files and directories
   - Reads files in chunks to handle large files efficiently

2. **Print function** (`print_files_with_sha256`):
   - Formats output in a readable format
   - Can show relative or absolute paths

3. **Advanced function** (`list_files_with_sha256_advanced`):
   - File filtering by extension
   - Exclude patterns support
   - Multiple output formats (dict, JSON, CSV)
   - Optional recursive scanning

4. **Progress bar version** (`list_files_with_sha256_progress`):
   - Shows progress for large directories (requires `tqdm` package)

The functions handle errors gracefully and work with large files by reading them in chunks rather than loading them entirely into memory.

